#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <inttypes.h>

typedef struct {
    uint64_t timestamp;
    uint8_t level;
    uint8_t source_len;
    unsigned char *source;
    uint16_t msg_len;
    unsigned char *message;
} log_entry;

static int read_exact(FILE *fp, void *buf, size_t n) {
    return fread(buf, 1, n, fp) == n;
}

static int read_u8(FILE *fp, uint8_t *v) {
    return read_exact(fp, v, 1);
}

static int read_le16(FILE *fp, uint16_t *v) {
    unsigned char b[2];
    if (!read_exact(fp, b, sizeof b)) {
        return 0;
    }
    *v = (uint16_t)b[0] | ((uint16_t)b[1] << 8);
    return 1;
}

static int read_le64_from_prefix(FILE *fp, unsigned char prefix[4], uint64_t *v) {
    unsigned char b[8];
    memcpy(b, prefix, 4);
    if (!read_exact(fp, b + 4, 4)) {
        return 0;
    }
    *v = ((uint64_t)b[0]) |
         ((uint64_t)b[1] << 8) |
         ((uint64_t)b[2] << 16) |
         ((uint64_t)b[3] << 24) |
         ((uint64_t)b[4] << 32) |
         ((uint64_t)b[5] << 40) |
         ((uint64_t)b[6] << 48) |
         ((uint64_t)b[7] << 56);
    return 1;
}

static void print_json_string(const unsigned char *s, size_t len) {
    size_t i;
    putchar('"');
    for (i = 0; i < len; i++) {
        unsigned char c = s[i];
        switch (c) {
        case '"':
            fputs("\\\"", stdout);
            break;
        case '\\':
            fputs("\\\\", stdout);
            break;
        case '\b':
            fputs("\\b", stdout);
            break;
        case '\f':
            fputs("\\f", stdout);
            break;
        case '\n':
            fputs("\\n", stdout);
            break;
        case '\r':
            fputs("\\r", stdout);
            break;
        case '\t':
            fputs("\\t", stdout);
            break;
        default:
            if (c < 0x20) {
                printf("\\u%04x", (unsigned int)c);
            } else {
                putchar(c);
            }
            break;
        }
    }
    putchar('"');
}

int main(int argc, char *argv[]) {
    FILE *fp;
    unsigned char header[16];
    int first = 1;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <blog_file>\n", argv[0]);
        return 1;
    }

    fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    if (!read_exact(fp, header, sizeof header)) {
        fprintf(stderr, "Error reading header\n");
        fclose(fp);
        return 1;
    }

    if (memcmp(header, "BLOG", 4) != 0) {
        fprintf(stderr, "Invalid BLOG magic\n");
        fclose(fp);
        return 1;
    }

    printf("[\n");

    for (;;) {
        unsigned char prefix[4];
        uint64_t timestamp;
        uint8_t level;
        uint8_t source_len;
        unsigned char *source;
        uint16_t msg_len;
        unsigned char *message;
        size_t nread;

        nread = fread(prefix, 1, sizeof prefix, fp);
        if (nread == 0) {
            break;
        }
        if (nread != sizeof prefix) {
            fprintf(stderr, "Truncated entry header\n");
            fclose(fp);
            return 1;
        }

        if (memcmp(prefix, "END!", 4) == 0) {
            unsigned char checksum[4];
            if (!read_exact(fp, checksum, sizeof checksum)) {
                fprintf(stderr, "Truncated footer\n");
                fclose(fp);
                return 1;
            }
            break;
        }

        if (!read_le64_from_prefix(fp, prefix, &timestamp)) {
            fprintf(stderr, "Truncated timestamp\n");
            fclose(fp);
            return 1;
        }
        if (!read_u8(fp, &level)) {
            fprintf(stderr, "Truncated level\n");
            fclose(fp);
            return 1;
        }
        if (!read_u8(fp, &source_len)) {
            fprintf(stderr, "Truncated source length\n");
            fclose(fp);
            return 1;
        }

        source = malloc((size_t)source_len + 1);
        if (!source) {
            fprintf(stderr, "Out of memory\n");
            fclose(fp);
            return 1;
        }
        if (!read_exact(fp, source, source_len)) {
            fprintf(stderr, "Truncated source\n");
            free(source);
            fclose(fp);
            return 1;
        }
        source[source_len] = '\0';

        if (!read_le16(fp, &msg_len)) {
            fprintf(stderr, "Truncated message length\n");
            free(source);
            fclose(fp);
            return 1;
        }

        message = malloc((size_t)msg_len + 1);
        if (!message) {
            fprintf(stderr, "Out of memory\n");
            free(source);
            fclose(fp);
            return 1;
        }
        if (!read_exact(fp, message, msg_len)) {
            fprintf(stderr, "Truncated message\n");
            free(source);
            free(message);
            fclose(fp);
            return 1;
        }
        message[msg_len] = '\0';

        if (!first) {
            printf(",\n");
        }
        first = 0;

        printf("  {\n");
        printf("    \"timestamp\": %" PRIu64 ",\n", timestamp);
        printf("    \"level\": %u,\n", (unsigned int)level);
        printf("    \"source\": ");
        print_json_string(source, source_len);
        printf(",\n");
        printf("    \"message\": ");
        print_json_string(message, msg_len);
        printf("\n");
        printf("  }");

        free(source);
        free(message);
    }

    printf("\n]\n");
    fclose(fp);
    return 0;
}
