typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned int u32;
typedef unsigned long u64;
typedef long i64;

#define SYS_read    0
#define SYS_write   1
#define SYS_open    2
#define SYS_close   3
#define SYS_lseek   8
#define SYS_mmap    9
#define SYS_exit    60

static long syscall1(long n, long a1) {
    long ret;
    __asm__ volatile(
        "syscall"
        : "=a"(ret)
        : "a"(n), "D"(a1)
        : "rcx", "r11", "memory"
    );
    return ret;
}

static long syscall3(long n, long a1, long a2, long a3) {
    long ret;
    __asm__ volatile(
        "syscall"
        : "=a"(ret)
        : "a"(n), "D"(a1), "S"(a2), "d"(a3)
        : "rcx", "r11", "memory"
    );
    return ret;
}

static long syscall6(long n, long a1, long a2, long a3,
                     long a4, long a5, long a6) {
    long ret;
    register long r10 __asm__("r10") = a4;
    register long r8 __asm__("r8") = a5;
    register long r9 __asm__("r9") = a6;

    __asm__ volatile(
        "syscall"
        : "=a"(ret)
        : "a"(n), "D"(a1), "S"(a2), "d"(a3),
          "r"(r10), "r"(r8), "r"(r9)
        : "rcx", "r11", "memory"
    );
    return ret;
}

static unsigned long str_len(const char *s) {
    unsigned long n = 0;
    while (s[n] != '\0') {
        n++;
    }
    return n;
}

static void write_fd(long fd, const void *buf, unsigned long len) {
    syscall3(SYS_write, fd, (long)buf, (long)len);
}

static void out_str(const char *s) {
    write_fd(1, s, str_len(s));
}

static void err_str(const char *s) {
    write_fd(2, s, str_len(s));
}

static void out_char(char c) {
    write_fd(1, &c, 1);
}

static void out_u64(u64 v) {
    u8 tmp[20];
    int i = 0;

    if (v == 0) {
        out_char('0');
        return;
    }

    while (v != 0) {
        tmp[i++] = (u8)('0' + (v % 10));
        v /= 10;
    }

    while (i > 0) {
        out_char((char)tmp[--i]);
    }
}

static void out_hex_digit(u8 v) {
    if (v < 10) {
        out_char((char)('0' + v));
    } else {
        out_char((char)('a' + (v - 10)));
    }
}

static void out_json_string(const u8 *s, unsigned long len) {
    unsigned long i;

    out_char('"');
    for (i = 0; i < len; i++) {
        u8 c = s[i];
        if (c == '"') {
            out_str("\\\"");
        } else if (c == '\\') {
            out_str("\\\\");
        } else if (c == '\b') {
            out_str("\\b");
        } else if (c == '\f') {
            out_str("\\f");
        } else if (c == '\n') {
            out_str("\\n");
        } else if (c == '\r') {
            out_str("\\r");
        } else if (c == '\t') {
            out_str("\\t");
        } else if (c < 0x20) {
            out_str("\\u00");
            out_hex_digit((u8)(c >> 4));
            out_hex_digit((u8)(c & 0x0f));
        } else {
            out_char((char)c);
        }
    }
    out_char('"');
}

static int bytes_eq(const u8 *a, const char *b, unsigned long n) {
    unsigned long i;
    for (i = 0; i < n; i++) {
        if (a[i] != (u8)b[i]) {
            return 0;
        }
    }
    return 1;
}

static u64 read_le64(const u8 *p) {
    u64 v = 0;
    int i;
    for (i = 0; i < 8; i++) {
        v |= ((u64)p[i]) << (8 * i);
    }
    return v;
}

static u16 read_le16(const u8 *p) {
    return (u16)((u16)p[0] | ((u16)p[1] << 8));
}

static int parse_and_print(const u8 *data, unsigned long size) {
    unsigned long pos = 16;
    int first = 1;

    if (size < 16 || !bytes_eq(data, "BLOG", 4)) {
        err_str("Invalid BLOG file\n");
        return 1;
    }

    out_str("[\n");

    while (pos < size) {
        u64 timestamp;
        u8 level;
        u8 source_len;
        const u8 *source;
        u16 msg_len;
        const u8 *message;

        if (size - pos >= 4 && bytes_eq(data + pos, "END!", 4)) {
            break;
        }

        if (size - pos < 12) {
            err_str("Truncated entry\n");
            return 1;
        }

        timestamp = read_le64(data + pos);
        pos += 8;
        level = data[pos++];
        source_len = data[pos++];

        if ((unsigned long)source_len > size - pos) {
            err_str("Truncated source\n");
            return 1;
        }
        source = data + pos;
        pos += source_len;

        if (size - pos < 2) {
            err_str("Truncated message length\n");
            return 1;
        }
        msg_len = read_le16(data + pos);
        pos += 2;

        if ((unsigned long)msg_len > size - pos) {
            err_str("Truncated message\n");
            return 1;
        }
        message = data + pos;
        pos += msg_len;

        if (!first) {
            out_str(",\n");
        }
        first = 0;

        out_str("  {\n");
        out_str("    \"timestamp\": ");
        out_u64(timestamp);
        out_str(",\n");
        out_str("    \"level\": ");
        out_u64((u64)level);
        out_str(",\n");
        out_str("    \"source\": ");
        out_json_string(source, source_len);
        out_str(",\n");
        out_str("    \"message\": ");
        out_json_string(message, msg_len);
        out_str("\n");
        out_str("  }");
    }

    out_str("\n]\n");
    return 0;
}

static int run(int argc, char **argv) {
    const char *path;
    long fd;
    long size;
    long map_addr;
    u8 *data;
    int rc;

    if (argc != 2) {
        err_str("Usage: logreader <blog_file>\n");
        return 1;
    }

    path = argv[1];
    fd = syscall3(SYS_open, (long)path, 0, 0);
    if (fd < 0) {
        err_str("Cannot open input file\n");
        return 1;
    }

    size = syscall3(SYS_lseek, fd, 0, 2);
    if (size < 16) {
        err_str("Input file is too small\n");
        syscall1(SYS_close, fd);
        return 1;
    }

    map_addr = syscall6(SYS_mmap, 0, size, 1, 2, fd, 0);
    syscall1(SYS_close, fd);

    if (map_addr < 0 && map_addr > -4096) {
        err_str("Cannot map input file\n");
        return 1;
    }

    data = (u8 *)map_addr;
    rc = parse_and_print(data, (unsigned long)size);
    return rc;
}

static void start_c(long *sp) {
    int argc = (int)sp[0];
    char **argv = (char **)(sp + 1);
    int rc = run(argc, argv);

    syscall1(SYS_exit, rc);
    for (;;) {
    }
}

__attribute__((naked, noreturn))
void _start(void) {
    __asm__ volatile(
        "mov %rsp, %rdi\n"
        "andq $-16, %rsp\n"
        "call start_c\n"
        "hlt\n"
    );
}
